// Procedural torus-knot sculpture. No model downloads or rendering dependencies.
(()=>{'use strict';const canvas=document.querySelector('#sculpture');const gl=canvas.getContext('webgl',{alpha:true,antialias:true,powerPreference:'low-power'});if(!gl)return;
const vertex=`attribute vec3 position;attribute vec3 normal;uniform mat4 projection;uniform mat4 model;varying vec3 vNormal;varying vec3 vPosition;void main(){vec4 p=model*vec4(position,1.);vPosition=p.xyz;vNormal=mat3(model)*normal;gl_Position=projection*p;}`;
const fragment=`precision mediump float;varying vec3 vNormal;varying vec3 vPosition;uniform float energy;void main(){vec3 n=normalize(vNormal);vec3 v=normalize(-vPosition);vec3 l=normalize(vec3(-.5,1.,1.4));vec3 l2=normalize(vec3(1.,-.3,.7));float dif=max(dot(n,l),0.);float rim=pow(1.-max(dot(n,v),0.),2.8);float spec=pow(max(dot(reflect(-l,n),v),0.),65.);float spec2=pow(max(dot(reflect(-l2,n),v),0.),28.);float bands=pow(.5+.5*sin(n.y*15.+n.x*9.),8.)*.22;vec3 base=vec3(.49,.70,.015);vec3 col=base*(.13+dif*.85+bands)+vec3(.86,1.,.36)*spec*.9+vec3(.38,.55,.05)*spec2*.7+vec3(.63,.87,.12)*rim*.65;col+=energy*vec3(.07,.09,0.);gl_FragColor=vec4(col,1.);}`;
function shader(type,source){const s=gl.createShader(type);gl.shaderSource(s,source);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw new Error('Sculpture shader unavailable');return s;}
let program;try{program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))return;}catch{return;}
gl.useProgram(program);const pos=[],norm=[],indices=[];const N=360,M=32;const TAU=Math.PI*2;
const center=t=>[(2+.65*Math.cos(3*t))*Math.cos(2*t),(2+.65*Math.cos(3*t))*Math.sin(2*t),.85*Math.sin(3*t)];
const sub=(a,b)=>a.map((v,i)=>v-b[i]);const unit=a=>{const d=Math.hypot(...a);return a.map(v=>v/d);};const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
for(let i=0;i<=N;i++){const t=i/N*TAU,c=center(t),tangent=unit(sub(center(t+.001),center(t-.001))),side=unit(cross(tangent,[0,0,1])),up=unit(cross(side,tangent));for(let j=0;j<=M;j++){const angle=j/M*TAU;const n=side.map((v,k)=>v*Math.cos(angle)+up[k]*Math.sin(angle));const radius=.45*(1+.055*Math.cos(t*80));pos.push(...c.map((v,k)=>v+n[k]*radius));norm.push(...n);if(i<N&&j<M){const a=i*(M+1)+j,b=a+M+1;indices.push(a,b,a+1,b,b+1,a+1);}}}
function attribute(name,data){const buffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(data),gl.STATIC_DRAW);const loc=gl.getAttribLocation(program,name);gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,3,gl.FLOAT,false,0,0);}
attribute('position',pos);attribute('normal',norm);const buffer=gl.createBuffer();gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,buffer);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,new Uint16Array(indices),gl.STATIC_DRAW);gl.enable(gl.DEPTH_TEST);gl.clearColor(0,0,0,0);
const projectionLocation=gl.getUniformLocation(program,'projection'),modelLocation=gl.getUniformLocation(program,'model'),energyLocation=gl.getUniformLocation(program,'energy');
let width=0,height=0,visible=true,dirty=true,clock=0,lastTime=0,lastFrame=0,pulse=0,level=0,frameId=0;const bins=new Uint8Array(128);const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function resize(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,1.6);width=Math.round(rect.width*dpr);height=Math.round(rect.height*dpr);if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}gl.viewport(0,0,width,height);const f=1/Math.tan(.57),aspect=width/Math.max(height,1),near=.1,far=100;gl.uniformMatrix4fv(projectionLocation,false,new Float32Array([f/aspect,0,0,0,0,f,0,0,0,0,(far+near)/(near-far),-1,0,0,2*far*near/(near-far),0]));dirty=true;schedule();}
function draw(timestamp){frameId=0;const paused=window.afterhoursMotion?.paused??reduced.matches;if(document.hidden||!visible)return;if(!paused&&timestamp-lastFrame<32){schedule();return;}const delta=lastTime?Math.min((timestamp-lastTime)/1000,.05):0;lastTime=timestamp;lastFrame=timestamp;if(!paused)clock+=delta;if(!paused||dirty){dirty=false;const analyser=window.afterhoursAudio?.analyser;if(analyser&&window.afterhoursAudio.playing&&!paused){analyser.getByteFrequencyData(bins);level=bins.slice(0,35).reduce((a,b)=>a+b,0)/(35*255);}else level*=.9;pulse*=.94;const x=.65+Math.sin(clock*.13)*.12,y=clock*.12-.2,z=-.45;const cx=Math.cos(x),sx=Math.sin(x),cy=Math.cos(y),sy=Math.sin(y),cz=Math.cos(z),sz=Math.sin(z);const s=1+(!paused?level*.10+pulse*.035:0);const model=[cy*cz*s,(sx*sy*cz+cx*sz)*s,(-cx*sy*cz+sx*sz)*s,0,-cy*sz*s,(-sx*sy*sz+cx*cz)*s,(cx*sy*sz+sx*cz)*s,0,sy*s,-sx*cy*s,cx*cy*s,0,0,.12,-7.6,1];gl.uniformMatrix4fv(modelLocation,false,new Float32Array(model));gl.uniform1f(energyLocation,level);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.drawElements(gl.TRIANGLES,indices.length,gl.UNSIGNED_SHORT,0);}if(!paused)schedule();}
function schedule(){if(!frameId&&visible&&!document.hidden)frameId=requestAnimationFrame(draw);}
new ResizeObserver(resize).observe(canvas);new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible){lastTime=0;dirty=true;schedule();}}).observe(canvas);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){lastTime=0;schedule();}});window.addEventListener('afterhours-pulse',()=>{pulse=1;schedule();});window.addEventListener('afterhours-motion',()=>{dirty=true;lastTime=0;schedule();});canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();document.documentElement.classList.remove('webgl-ready');visible=false;});canvas.addEventListener('webglcontextrestored',()=>location.reload());document.documentElement.classList.add('webgl-ready');resize();
})();
